<div class="page-head"><div><h1><?= e(__('Giving')) ?></h1><p><?= e(__('Donations recorded manually or received online through Stripe.')) ?></p></div>
<div class="actions"><a class="btn" href="<?= e(url('/giving/statements')) ?>"><?= e(__('Statements')) ?></a><?php if (can('giving.manage')): ?><a class="btn" href="<?= e(url('/giving/import')) ?>"><?= e(__('Import bank deposits')) ?></a><?php endif; ?><details class="usermenu"><summary class="btn"><?= e(__('Export')) ?></summary><div class="menu"><a href="<?= e(url('/giving/export', ['from' => $from, 'to' => $to])) ?>"><?= e(__('CSV (all details)')) ?></a><a href="<?= e(url('/giving/export', ['from' => $from, 'to' => $to, 'format' => 'xero'])) ?>"><?= e(__('Xero bank statement CSV')) ?></a><a href="<?= e(url('/giving/export', ['from' => $from, 'to' => $to, 'format' => 'myob'])) ?>"><?= e(__('MYOB CSV')) ?></a></div></details><a class="btn" href="<?= e(url('/give')) ?>" target="_blank"><?= e(__('Public giving page')) ?></a></div></div>
<form class="filters" method="get" action="<?= e(base_path() . '/index.php') ?>"><input type="hidden" name="r" value="/giving">
<label><?= e(__('From')) ?><input type="date" name="from" value="<?= e($from) ?>"></label><label><?= e(__('To')) ?><input type="date" name="to" value="<?= e($to) ?>"></label><label><?= e(__('Fund')) ?><select name="fund"><?= options($funds, $fund, __('All funds')) ?></select></label><button class="btn"><?= e(__('Show')) ?></button></form>
<div class="grid-4" style="margin-bottom:18px"><?php foreach ($byFund as $f): ?><div class="stat"><div class="num"><?= e(fmt_money((int)$f['total'])) ?></div><div class="lbl"><?= e($f['name'] ?: __('Unallocated')) ?> · <?= (int)$f['n'] ?></div></div><?php endforeach; ?></div>
<div class="split">
<div class="card table-wrap"><table><thead><tr><th><?= e(__('Date')) ?></th><th><?= e(__('Donor')) ?></th><th><?= e(__('Fund')) ?></th><th><?= e(__('Amount')) ?></th><th><?= e(__('Method')) ?></th><th><span class="sr-only"><?= e(__('Actions')) ?></span></th></tr></thead><tbody>
<?php foreach ($rows as $d): ?><tr><td class="small"><?= e(fmt_date($d['received_on'] ?: $d['created_at'])) ?></td><td><?= e(person_name($d) ?: ($d['donor_name'] ?: __('Anonymous'))) ?><div class="small muted"><?= e($d['receipt_no']) ?></div></td><td><?= e($d['fund']) ?></td><td><?= e(fmt_money($d['status'] === 'refunded' ? Gifts::gross($d) : (int)$d['amount_cents'], $d['currency'])) ?> <?= $d['status'] !== 'paid' ? badge($d['status']) : '' ?><?= $d['status'] === 'paid' && (int)$d['refunded_cents'] ? '<div class="small muted">' . e(__('%s refunded', fmt_money((int)$d['refunded_cents'], $d['currency']))) . '</div>' : '' ?></td><td class="small"><?= e(strtoupper($d['method'])) ?></td>
<td><?php if ($d['status'] === 'paid' && can('giving.manage') && ($d['person_id'] || $d['donor_email'])): ?><form method="post" action="<?= e(url('/giving/' . $d['id'] . '/receipt')) ?>"><?= csrf_field() ?><button class="btn btn-sm"><?= e(__('Email receipt')) ?></button></form><?php endif; ?><?php if ($d['status'] === 'paid' && (int)$d['amount_cents'] > 0 && can('giving.manage')): ?> <a class="btn btn-sm" href="<?= e(url('/giving/' . $d['id'] . '/refund')) ?>"><?= e(__('Refund')) ?></a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6" class="empty"><?= e(__('No donations in this period.')) ?></td></tr><?php endif; ?>
</tbody></table></div>
<div><?php $rec = DB::all("SELECT rg.*, p.first_name, p.last_name, p.preferred_name, f.name AS fund FROM {p}recurring_gifts rg LEFT JOIN {p}people p ON p.id = rg.person_id LEFT JOIN {p}funds f ON f.id = rg.fund_id WHERE rg.status IN ('active','past_due') ORDER BY rg.created_at DESC"); if ($rec): ?>
<div class="card"><h2 class="h3"><?= e(__('Regular gifts')) ?></h2><ul class="list-plain small"><?php foreach ($rec as $g): ?><li><?= e(person_name($g) ?: $g['donor_name']) ?> · <?= e(fmt_money((int)$g['amount_cents'])) ?> / <?= e(__($g['frequency'])) ?> · <?= e($g['fund']) ?> <?= $g['status'] === 'past_due' ? badge('failed') : '' ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if (can('giving.manage')): ?><div class="card"><h2 class="h3"><?= e(__('Record a donation')) ?></h2>
<form method="post" action="<?= e(url('/giving')) ?>" class="form"><?= csrf_field() ?>
  <label><?= e(__('Donor')) ?><select name="person_id"><?= options(people_options(), null, __('— Not in database —')) ?></select></label>
  <label><?= e(__('Or donor name')) ?><input name="donor_name"></label>
  <div class="grid-2"><label><?= e(__('Amount ($)')) ?><input name="amount" required inputmode="decimal"></label><label><?= e(__('Date received')) ?><input type="date" name="received_on" value="<?= e(date('Y-m-d')) ?>"></label>
  <label><?= e(__('Fund')) ?><select name="fund_id"><?= options($funds) ?></select></label><label><?= e(__('Method')) ?><select name="method"><?= options(['eft' => __('Bank transfer'), 'cash' => __('Cash'), 'cheque' => __('Cheque'), 'other' => __('Other')]) ?></select></label></div>
  <label><?= e(__('Notes')) ?><input name="notes"></label>
  <button class="btn btn-primary"><?= e(__('Record')) ?></button>
</form></div><?php endif; ?></div>
</div>
